(1003177, 118385, 2780, '<td valign="top">I would have cropped a bit lower to get rid of the ''horizon'' in the photo.</td>', 'I would have cropped a bit lower to get rid of the ''horizon'' in the photo.', '2004-11-10 08:55:05.000000', NULL, 1),
(1003178, 120207, 2780, '<td valign="top">I like the colour treatment, but I''m not really a fan of photos of figurines.</td>', 'I like the colour treatment, but I''m not really a fan of photos of figurines.', '2004-11-10 08:55:40.000000', NULL, 1),
