(1004819, 119882, 29186, '<td valign="top">pretty good. very nice lighting. good color</td>', 'pretty good. very nice lighting. good color', '2004-11-10 18:34:05.000000', NULL, 1),
(1004820, 118671, 6999, '<td valign="top">The light seems a bit strong, and the high-key background doesn''t quite work for me, especially with those partially visible elements to the left. I would have thught a softer light would give a gentler feel to the image - I don''t mean less bright, just more diffuse, to lighten the extremities of those shadows.</td>', 'The light seems a bit strong, and the high-key background doesn''t quite work for me, especially with those partially visible elements to the left. I would have thught a softer light would give a gentler feel to the image - I don''t mean less bright, just more diffuse, to lighten the extremities of those shadows.', '2004-11-10 18:34:16.000000', NULL, 1),
(1004821, 118465, 14735, '<td valign="top">I like that fatal error but would be interesting in if had a bit more DOP</td>', 'I like that fatal error but would be interesting in if had a bit more DOP', '2004-11-10 18:34:18.000000', NULL, 1),
