(1006124, 120150, 19670, '<td valign="top">Very cool. Well done!</td>', 'Very cool. Well done!', '2004-11-11 12:45:51.000000', NULL, 1),
(1006125, 119255, 19670, '<td valign="top">I really like the patterns found at the edge of the leaf in the liquid. Reminds me of fractals. Also see a face with the droplet as an eye.</td>', 'I really like the patterns found at the edge of the leaf in the liquid. Reminds me of fractals. Also see a face with the droplet as an eye.', '2004-11-11 12:46:59.000000', NULL, 1),
(1006126, 118423, 19670, '<td valign="top">Looking forward to our own family addition myself! Enjoy your special time.</td>', 'Looking forward to our own family addition myself! Enjoy your special time.', '2004-11-11 12:48:41.000000', NULL, 1),
(1006127, 120269, 18552, '<td valign="top">Interesting subject, nice composition and good lighting. I really like the texture that shows on the round part of the key that is in focus. To me, your picture would have been so much more interesting if more of the key had been in focus.</td>', 'Interesting subject, nice composition and good lighting. I really like the texture that shows on the round part of the key that is in focus. To me, your picture would have been so much more interesting if more of the key had been in focus.', '2004-11-11 12:49:24.000000', NULL, 1),
(1006129, 119011, 29309, '<td valign="top">I like the color and the crop. When I think of macro photography, i do not see the complete image</td>', 'I like the color and the crop. When I think of macro photography, i do not see the complete image', '2004-11-11 12:50:23.000000', NULL, 1),
(1006130, 119951, 23312, '<td valign="top">I think that the blur on the bottom/close objects is a bit too much - it''s sort of a barrier for the eye to get back into the rest of the picture.  I''d be tempted to cop a bit of it out.</td>', 'I think that the blur on the bottom/close objects is a bit too much - it''s sort of a barrier for the eye to get back into the rest of the picture.  I''d be tempted to cop a bit of it out.', '2004-11-11 12:50:47.000000', NULL, 1),
