(1008193, 120263, 29363, '<td valign="top">Divided down the middle --- should be less balanced.</td>', 'Divided down the middle --- should be less balanced.', '2004-11-12 16:56:50.000000', NULL, 1),
(1008197, 120093, 29363, '<td valign="top">Cool abstract quality and cute title.</td>', 'Cool abstract quality and cute title.', '2004-11-12 16:57:50.000000', NULL, 1),
(1008199, 119616, 24454, '<td valign="top">I''m specifically voting this up because it''s an interesting picture, and I know you are probably getting lots of comments that it''s not a macro (that happened to me on the last macro challenge :)  BUT the challenge doesn''t require it to be an official "macro" but only an extreme close-up, which this is -- and I like it!    So good luck!  :)</td>', 'I''m specifically voting this up because it''s an interesting picture, and I know you are probably getting lots of comments that it''s not a macro (that happened to me on the last macro challenge :)  BUT the challenge doesn''t require it to be an official "macro" but only an extreme close-up, which this is -- and I like it!    So good luck!  :)', '2004-11-12 16:59:55.000000', NULL, 1),
(1008201, 118979, 24454, '<td valign="top">Ooooh.   That''s a good one :)</td>', 'Ooooh.   That''s a good one :)', '2004-11-12 17:00:49.000000', NULL, 1),
(1008204, 120178, 24454, '<td valign="top">THAT is cool! ! ! ! !</td>', 'THAT is cool! ! ! ! !', '2004-11-12 17:02:41.000000', NULL, 1),
(1008206, 119027, 29363, '<td valign="top">Does nothing for me.</td>', 'Does nothing for me.', '2004-11-12 17:03:42.000000', NULL, 1),
