(1008214, 118540, 29161, '<td valign="top">I like this. I dunno what it is, but I like it. Nice abstract.</td>', 'I like this. I dunno what it is, but I like it. Nice abstract.', '2004-11-12 17:06:38.000000', NULL, 1),
(1008217, 118331, 29363, '<td valign="top">Seen it before --- lacks creativity.</td>', 'Seen it before --- lacks creativity.', '2004-11-12 17:07:18.000000', NULL, 1),
